function safeRead(key, fallback) {
  try { const value = JSON.parse(localStorage.getItem(key) || "null"); return value ?? fallback; } catch { return fallback; }
}
const CLOUD_KEYS=["osrsflipit-profiles","osrsflipit-columns","osrsflipit-column-widths","osrsflipit-detail-tiles","osrsflipit-filters","osrsflipit-watch","osrsflipit-alerts","osrsflipit-rules","osrsflipit-mini-ge","osrsflipit-sound","osrsflipit-sound-volume","osrsflipit-sound-type","osrsflipit-theme","osrsflipit-chart-layers","osrsflipit-recipe-favs","osrsflipit-flip-log","osrsflipit-bankroll","osrsflipit-portfolio","osrshub-dashboard-pins","osrshub-account"];
function collectCloudData(){const data={};CLOUD_KEYS.forEach(k=>{try{const raw=localStorage.getItem(k);if(raw!==null)data[k]=JSON.parse(raw)}catch{}});return data}
function applyCloudData(data){if(!data||typeof data!=="object")return 0;let count=0;for(const k of CLOUD_KEYS){if(!(k in data))continue;try{localStorage.setItem(k,JSON.stringify(data[k]));count++}catch{}}return count}
async function cloudFetch(path,options={}){const res=await fetch(path,{credentials:"include",...options,headers:{Accept:"application/json",...(options.headers||{})}});const payload=await res.json().catch(()=>null);if(!res.ok)throw new Error(payload?.error||`Cloud request failed (${res.status})`);return payload}
function parseGp(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : "";
  const raw = String(value ?? "").trim().toLowerCase().replace(/,/g, "");
  if (!raw) return "";
  const m = raw.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/);
  if (!m) { const n=Number(raw); return Number.isFinite(n) ? n : ""; }
  const multipliers = { k: 1e3, m: 1e6, b: 1e9 };
  return Number(m[1]) * (m[2] ? multipliers[m[2]] : 1);
}
function levenshtein(a,b){const prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let cur=[i];for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));for(let j=0;j<=b.length;j++)prev[j]=cur[j]}return prev[b.length]}
function fuzzyScore(query,text){
  const q=query.toLowerCase().trim().replace(/[^a-z0-9\s']/g," ").replace(/\s+/g," ");
  const t=text.toLowerCase().replace(/[^a-z0-9\s']/g," ").replace(/\s+/g," ").trim();
  if(!q)return 0;
  if(t===q)return 100000;
  const qt=q.split(" ").filter(Boolean), tt=t.split(" ").filter(Boolean);
  let score=0, matched=0;
  for(const token of qt){
    let best=0;
    for(const word of tt){
      if(word===token)best=Math.max(best,1000);
      else if(word.startsWith(token))best=Math.max(best,820-Math.max(0,word.length-token.length)*8);
      else if(word.includes(token))best=Math.max(best,650-Math.max(0,word.indexOf(token))*10);
      else {const d=levenshtein(token,word), maxLen=Math.max(token.length,word.length);if(d<=Math.max(1,Math.floor(maxLen*.34)))best=Math.max(best,560-d*65-Math.max(0,maxLen-token.length)*8)}
    }
    if(best>0){score+=best;matched++}
  }
  const all=qt.join(" ");
  if(t.includes(all))score+=1800;
  if(t.startsWith(all))score+=2200;
  const coverage=matched/qt.length;
  score+=coverage*900;
  if(matched===0||coverage<.5)return -1;
  return score-(t.length-q.length)*0.35;
}
function fuzzyItems(items,query,limit=10){const q=query.trim();if(!q)return [];return items.map(x=>({x,score:fuzzyScore(q,x.name)})).filter(a=>a.score>=0).sort((a,b)=>b.score-a.score||a.x.name.localeCompare(b.x.name)).slice(0,limit).map(a=>a.x)}
function ItemSearchSuggestions({items,value,onChange,onSelect,compact=false}){const matches=useMemo(()=>fuzzyItems(items,value,7),[items,value]);if(!value.trim()||!matches.length)return null;return <div className={`itemSearchSuggestions ${compact?"compact":""}`}>{matches.map((x,i)=><button key={x.id} className={i===0?"bestMatch":""} onClick={()=>{onChange(x.name);onSelect(x)}}><img src={iconUrl(x.icon)} onError={e=>e.currentTarget.style.display="none"}/><span><strong>{x.name}</strong><small>{money(x.sell)} · {money(x.margin)} margin</small></span><ChevronRight size={14}/></button>)}</div>}
function enrich(row, mapping, daily = {}) {
  const m = mapping[row.id] || {};
  const buy = Number(row.high ?? 0), sell = Number(row.low ?? 0), tax = taxFor(sell), margin = buy > 0 && sell > 0 ? buy - sell - tax : 0;
  const volume = daily[row.id] ? (daily[row.id].highPriceVolume || 0) + (daily[row.id].lowPriceVolume || 0) : 0;
  const limit = Number(m.limit || 0), potentialProfit = margin * limit, alch = Number(m.highalch ?? m.highAlch ?? 0) || 0;
  return {...row,...m,buy,sell,tax,margin,roi:buy?margin/buy*100:0,volume,limit,potentialProfit,limitProfit:potentialProfit,alch,buyUpdated:row.lowTime?row.lowTime*1000:null,sellUpdated:row.highTime?row.highTime*1000:null,lastUpdated:Math.max(row.highTime||0,row.lowTime||0)*1000||null,flipScore:0};
}
async function api(path) {
  const key = `osrsflipit-cache:${path}`;
  const ttl = path.startsWith("/timeseries") ? 5 * 60 * 1000 : 45 * 1000;
  try {
    const cached = JSON.parse(sessionStorage.getItem(key) || "null");
    if (cached && Date.now() - cached.at < ttl) return cached.data;
  } catch {}
  try {
    const res = await fetch(`${API}${path}`, { headers: { "User-Agent": "OSRS-Hub/1.0 (Grand Exchange analytics)" } });
    if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
    const data = await res.json();
    try { sessionStorage.setItem(key, JSON.stringify({at:Date.now(),data})); } catch {}
    return data;
  } catch (e) {
    try {
      const cached = JSON.parse(sessionStorage.getItem(key) || "null");
      if (cached?.data) return cached.data;
    } catch {}
    throw e;
  }
}

function parseThreshold(value){
  const raw=String(value??"").trim().toLowerCase().replace(/\s+/g,"").replace(/,/g,"");
  if(!raw)return 0;
  const m=raw.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/);
  if(!m)return Math.max(0,Number(raw)||0);
  const mult=m[2]==="k"?1e3:m[2]==="m"?1e6:m[2]==="b"?1e9:1;
  return Math.max(0,Number(m[1])*mult||0);
}
function clamp(n,a=0,b=100){return Math.max(a,Math.min(b,n))}
function scoreItem(x){
  const roiScore=clamp((x.roi/5)*100);
  const marginScore=clamp((Math.log10(Math.max(0,x.margin)+1)/Math.log10(250000+1))*100);
  const volumeScore=clamp((Math.log10(Math.max(0,x.volume)+1)/Math.log10(250000+1))*100);
  const capitalScore=clamp((x.buy>0?(x.margin/x.buy)*1000000/50000:0));
  const liquidityScore=clamp((x.volume/Math.max(1,Math.ceil(1000000/Math.max(1,x.buy))))*100);
  const riskScore=Math.round(clamp(volumeScore*.42+liquidityScore*.28+clamp(100-Math.max(0,x.roi-3)*7)*.18+clamp(100-(x.buy/50000000)*35)*.12));
  const penalty=x.buy>100000000?Math.min(30,Math.log10(x.buy/100000000+1)*30):0;
  const flipScore=Math.round(clamp(roiScore*.24+marginScore*.24+volumeScore*.22+riskScore*.18+capitalScore*.12-penalty));
  const capitalEfficiency=x.buy>0?(x.margin/x.buy)*1000000:0;
  const limitCost=x.buy>0&&x.limit>0?x.buy*x.limit:0;
  const slotQty=Math.max(1,Math.min(x.limit||1,Math.floor(1000000/Math.max(1,x.buy))));
  const slotProfit=x.margin>0?x.margin*slotQty:0;
  const riskLabel=riskScore>=75?"Low":riskScore>=50?"Medium":"High";
  return {...x,flipScore,riskScore,riskLabel,capitalEfficiency,slotProfit,limitCost,scoreBreakdown:{roi:Math.round(roiScore),margin:Math.round(marginScore),volume:Math.round(volumeScore),risk:riskScore,capital:Math.round(capitalScore)}};
}
function iconUrl(icon) { return icon ? `https://oldschool.runescape.wiki/images/${encodeURIComponent(icon.replace(/ /g, "_"))}` : ""; }
function closeOnEscape(handler) { useEffect(() => { const f = e => e.key === "Escape" && handler(); window.addEventListener("keydown", f); return () => window.removeEventListener("keydown", f); }, [handler]); }

