function Calculators({items}){
  const [mode,setMode]=useState("sets"),[sortKey,setSortKey]=useState("profit"),[sortDir,setSortDir]=useState("desc");
  const sets=useMemo(()=>SET_RECIPES.map(([name,parts,setName])=>{const ps=parts.map(n=>recipeItemId(items,n));const set=recipeItemId(items,setName);const pieces=ps.reduce((a,x)=>a+(x?.sell||0),0);const setSell=set?.sell||0;return{name,setName,pieces,setSell,profit:pieces-setSell-taxFor(setSell),parts:ps}}).filter(x=>x.setSell>0&&x.parts.every(Boolean)),[items]);
  const potions=useMemo(()=>{const map=new Map();items.forEach(x=>{const m=x.name.match(/^(.*)\(([1-4])\)$/);if(m){const key=m[1].trim();const d=Number(m[2]);if(!map.has(key))map.set(key,{});map.get(key)[d]=x}});return [...map.entries()].map(([name,d])=>{const p1=d[1],p2=d[2],p3=d[3],p4=d[4];if(!p4)return null;const rows=[1,2,3].filter(n=>d[n]).map(n=>{const input=d[n].sell||0;const count=4/n;const output=p4.sell||0;const cost=input*count;const revenue=output-taxFor(output);return {from:n,cost,revenue,profit:revenue-cost,volume:d[n].volume||0}});return {name,p4,rows,volume:p4.volume||0}}).filter(Boolean).slice(0,80)},[items]);
  return <section className="calculatorPage"><div className="calcTabs"><button className={mode==="sets"?"active":""} onClick={()=>setMode("sets")}>Item set disassembly</button><button className={mode==="potions"?"active":""} onClick={()=>setMode("potions")}>Potion decanting</button></div>{mode==="sets"?<div className="calcCard"><div className="sectionhead"><div><div className="eyebrow">SET DISASSEMBLY</div><h2>Set versus individual pieces.</h2></div><p>Live GE sell prices · tax-aware.</p></div><div className="calcGrid calcSortable">{[...sets].sort((a,b)=>(sortDir==="desc"?1:-1)*((sortKey==="profit"?b.profit-a.profit:a.setSell-b.setSell))).map(x=><div className="calcRow" key={x.name}><div><strong>{x.name}</strong><small>{x.parts.map((p,i)=><span key={i}>{p.name}{i<x.parts.length-1?" · ":""}</span>)}</small></div><div><span>Pieces</span><b>{money(x.pieces)}</b></div><div><span>Set sell</span><b>{money(x.setSell)}</b></div><strong className={x.profit>=0?"green":"redtxt"}>{x.profit>=0?"Disassemble ":"Assemble "}{money(Math.abs(x.profit))}</strong></div>)}</div>{!sets.length&&<div className="emptybox">Set components are not available in the current live mapping.</div>}</div>:<div className="calcCard"><div className="sectionhead"><div><div className="eyebrow">POTION DECANTING</div><h2>Compare every live dose route.</h2></div><p>Bob Barter decants for free; GE tax is applied to the sale.</p></div><div className="tablewrap"><table className="sortableCalc"><thead><tr>{[["name","Potion"],["route","Route"],["cost","Input cost"],["revenue","4-dose value after tax"],["profit","Profit / 4 doses"],["volume","Input volume"]].map(([k,l])=><th key={k}><button className="thbtn" onClick={()=>{if(sortKey===k)setSortDir(v=>v==="desc"?"asc":"desc");else{setSortKey(k);setSortDir("desc")}}}>{l}<ArrowUpDown size={12}/></button></th>)}</tr></thead><tbody>{[...potions.flatMap(x=>x.rows.map(r=>({...r,potionName:x.name,route:`${r.from}-dose → 4-dose`})))] .sort((a,b)=>{const av=sortKey==="name"?a.potionName:sortKey==="route"?a.route:a[sortKey];const bv=sortKey==="name"?b.potionName:sortKey==="route"?b.route:b[sortKey];return (sortDir==="desc"?1:-1)*(typeof av==="string"?av.localeCompare(bv):bv-av)}).map(r=><tr key={`${r.potionName}-${r.from}`}><td>{r.potionName}</td><td>{r.route}</td><td>{money(r.cost)}</td><td>{money(r.revenue)}</td><td><strong className={r.profit>=0?"green":"redtxt"}>{money(r.profit)}</strong></td><td>{num(r.volume)}</td></tr>)}</tbody></table></div></div>}</section>
}

function Movers({movers,items,onSelect,filters,page,setPage}){const total=Math.max(movers.up.length,movers.down.length);const visible=Math.min(100,page*25);return <section><div className="sectionhead"><div><div className="eyebrow">MARKET MOVERS</div><h2>What moved today.</h2></div><p>Top {visible} shown · maximum 100.</p></div><div className="moverFilters">{[["Min price","moverMinPrice","setMoverMinPrice"],["Max price","moverMaxPrice","setMoverMaxPrice"],["Min volume","moverMinVolume","setMoverMinVolume"],["Max volume","moverMaxVolume","setMoverMaxVolume"]].map(([l,v,s])=><label key={v}>{l}<input value={filters[v]} onChange={e=>filters[s](e.target.value)} placeholder="Any"/></label>)}</div><MarketOpportunityLab items={items} onSelect={onSelect}/><div className="movegrid"><MoveCol title="Rising" icon={<TrendingUp/>} rows={movers.up.slice(0,visible)} onSelect={onSelect}/><MoveCol title="Falling" icon={<TrendingDown/>} rows={movers.down.slice(0,visible)} onSelect={onSelect}/></div>{visible<total&&<button className="loadMore" onClick={()=>setPage(Math.min(4,page+1))}>Load 25 more <span>{Math.min(100,total)-visible} remaining</span></button>}</section>}
function MoveCol({title,icon,rows,onSelect}){return <div className="movecol"><div className="movetitle">{icon}<strong>{title}</strong><span>Top 50</span></div>{rows.map((x,i)=><button className="moverow" key={x.id} onClick={()=>onSelect(x)}><span className="rank">{String(i+1).padStart(2,"0")}</span><img className="itemIcon" src={iconUrl(x.icon)}/><span className="mname"><strong>{x.name}</strong><small>{money(x.sell)} sell · {num(x.volume)} vol/24h</small></span><b className={x.change>=0?"green":"redtxt"}>{pct(x.change)}</b><ChevronRight size={15}/></button>)}</div>}
function Watch({watched,onSelect,toggleWatch}){const sorted=[...watched].sort((a,b)=>(b.margin-a.margin)||(b.flipScore-a.flipScore));return <section><div className="sectionhead"><div><div className="eyebrow">WATCHLIST INTELLIGENCE</div><h2>Your market radar.</h2></div><p>{watched.length}/25 saved · sorted by current opportunity</p></div><div className="cards">{sorted.length?sorted.map(x=>{const spreadPct=x.buy?x.margin/x.buy*100:0;const liquidity=x.volume>=5000?"High":x.volume>=1000?"Medium":"Low";return <button className="watchcard" key={x.id} onClick={()=>onSelect(x)}><img className="itemIcon bigIcon" src={iconUrl(x.icon)}/><div><strong>{x.name}</strong><small>{money(x.buy)} → {money(x.sell)} · {liquidity} liquidity</small><small>ROI {pct(spreadPct)} · Flip Score {x.flipScore}/100</small></div><b className={x.margin>=0?"green":"redtxt"}>{money(x.margin)}</b><span onClick={e=>{e.stopPropagation();toggleWatch(x.id)}}><X size={16}/></span></button>}):<div className="emptybox">Star items in the market table to keep them here.</div>}</div></section>}
function WatchTicker({watched,onSelect}){return <div className="ticker"><div className="tickerTrack">{[...watched,...watched].map((x,i)=>{const change=x.buy?((x.sell-x.buy)/x.buy)*100:0;return <button key={`${x.id}-${i}`} onClick={()=>onSelect(x)}><span>{x.name}</span><b className={change>=0?"green":"redtxt"}>{change>=0?"↗":"↘"} {pct(change)}</b></button>})}{!watched.length&&<span className="tickerEmpty">Star an item to add it to the market ticker.</span>}</div></div>}
function RuleModal({items,existing,onClose,onSave}){const [q,setQ]=useState(existing?.name||"");const [id,setId]=useState(existing?.id||items[0]?.id);const [metric,setMetric]=useState(existing?.metric||"sell");const [direction,setDirection]=useState(existing?.direction||"above");const [value,setValue]=useState(existing?.value||100000);closeOnEscape(onClose);const found=fuzzyItems(items,q,7);return <div className="modalback" onClick={onClose}><div className="modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={onClose}><X/></button><div className="eyebrow">{existing?"EDIT ALERT":"NEW ALERT"}</div><h2>{existing?"Change the rule.":"Watch a price."}</h2><label>Item</label><input value={q} onChange={e=>{setQ(e.target.value);const f=fuzzyItems(items,e.target.value,1)[0];if(f)setId(f.id)}} placeholder="Search item…"/>{q&&<div className="suggest">{found.map(x=><button key={x.id} onClick={()=>{setId(x.id);setQ(x.name)}}>{x.name}</button>)}</div>}<div className="twocol"><div><label>Metric</label><select value={metric} onChange={e=>setMetric(e.target.value)}><option value="sell">Sell price</option><option value="buy">Buy price</option><option value="margin">Margin</option><option value="roi">ROI</option></select></div><div><label>Condition</label><select value={direction} onChange={e=>setDirection(e.target.value)}><option value="above">rises above</option><option value="below">drops below</option></select></div></div><label>Threshold</label><input value={value} onChange={e=>setValue(parseGp(e.target.value))} placeholder="100k, 2.5m…"/><button className="primary wide" onClick={()=>{const x=items.find(x=>x.id===id);onSave({id,name:x?.name||q||"Unknown",itemId:x?.id||id,metric,direction,value:Number(value)})}}>{existing?"Save changes":"Create alert"}</button></div></div>}

function ColumnResizeEffect({resizingColumn,setResizingColumn,setColumnWidths}){useEffect(()=>{if(!resizingColumn)return;const move=e=>setColumnWidths(ws=>({...ws,[resizingColumn.key]:Math.max(70,resizingColumn.startWidth+e.clientX-resizingColumn.startX)}));const up=()=>setResizingColumn(null);window.addEventListener("pointermove",move);window.addEventListener("pointerup",up,{once:true});return()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up)}} ,[resizingColumn]);return null}

